class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        def findBound(findFirst: bool) -> int:
            lo, hi, ans = 0, len(nums) - 1, -1
            while lo <= hi:
                mid = lo + (hi - lo) // 2
                if nums[mid] == target:
                    ans = mid
                    if findFirst:
                        hi = mid - 1
                    else:
                        lo = mid + 1
                elif nums[mid] < target:
                    lo = mid + 1
                else:
                    hi = mid - 1
            return ans
        return [findBound(True), findBound(False)]

